static void
combobox_spawn_update_alternatives (const gchar *item, const gchar *default_text)
{
	const gchar *group = NULL;
	gchar *candidate = NULL;
	gchar *argv[6];
	GError *error = NULL;
	GPid pid = 0;

	if (g_strcmp0(item, "webbrowser") == 0)
		group = "x-www-browser";
	else if (g_strcmp0(item, "terminal_manager") == 0)
		group = "x-terminal-emulator";
	if (group == NULL || default_text == NULL || default_text[0] == '\0')
		return;

	candidate = g_path_is_absolute(default_text) ?
		g_strdup(default_text) : g_build_filename("/usr/bin", default_text, NULL);
	if (!g_file_test(candidate, G_FILE_TEST_IS_EXECUTABLE))
	{
		g_free(candidate);
		return;
	}

	argv[0] = (gchar *)"pkexec";
	argv[1] = (gchar *)"update-alternatives";
	argv[2] = (gchar *)"--set";
	argv[3] = (gchar *)group;
	argv[4] = candidate;
	argv[5] = NULL;
	if (!g_spawn_async(NULL, argv, NULL,
	                    G_SPAWN_SEARCH_PATH | G_SPAWN_DO_NOT_REAP_CHILD,
	                    NULL, NULL, &pid, &error))
	{
		g_warning("combobox: failed to launch update-alternatives: %s",
		          error != NULL ? error->message : "unknown error");
		g_clear_error(&error);
	}
	else
	{
		g_child_watch_add_full(G_PRIORITY_DEFAULT_IDLE, pid,
		                       combobox_close_child_pid, NULL, NULL);
	}
	g_free(candidate);
}

